// Famicom moon sprites (32x32), New Moon to Full Moon
static const uint8_t* const kRetroMoons[8] = { gRetroMoon_new, gRetroMoon_2of8, gRetroMoon_3of8, gRetroMoon_half, gRetroMoon_5of8, gRetroMoon_6of8, gRetroMoon_7of8, gRetroMoon_full };

constexpr int kRetroPortraitSize = 48;
// 48x48 portrait for a party member by name (case-insensitive), or nullptr.
inline const uint8_t* RetroPortrait(const char* name) {
    struct Entry { const char* name; const uint8_t* tex; };
    static const Entry kEntries[] = {
        { "link", gRetroPortrait_link },
        { "saria", gRetroPortrait_saria },
        { "ruto", gRetroPortrait_ruto },
        { "zelda", gRetroPortrait_zelda },
        { "impa", gRetroPortrait_impa },
        { "malon", gRetroPortrait_malon },
        { "darunia", gRetroPortrait_darunia },
        { "nabooru", gRetroPortrait_nabooru },
        { "sheik", gRetroPortrait_sheik },
        { "kaepora", gRetroPortrait_kaepora },
    };
    for (const Entry& e : kEntries) {
        size_t n = strlen(e.name);
        bool same = strlen(name) == n;
        for (size_t i = 0; same && i < n; i++) {
            char c = name[i];
            same = (c >= 'A' && c <= 'Z' ? (char)(c - 'A' + 'a') : c) == e.name[i];
        }
        if (same) {
            return e.tex;
        }
    }
    return nullptr;
}
